Bug: in `func (b *DefaultBinder) bindData(...)` the map branch is:

```go
	// Map
	if typ.Kind() == reflect.Map {
		for k, v := range data {
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
		}
		return nil
	}
```

This panics (`reflect: SetMapIndex: value of type string is not assignable to type []string`) when the destination is `map[string][]string`, and for `map[string]interface{}` it stores only a single string instead of the whole value slice.

Replace that branch with exactly:

```go
	// Map
	if typ.Kind() == reflect.Map {
		if typ.Key().Kind() != reflect.String {
			return errors.New("binding element must be a map with string keys")
		}
		elemType := typ.Elem()
		sliceType := reflect.TypeOf(data).Elem() // []string
		for k, v := range data {
			key := reflect.ValueOf(k)
			switch {
			case sliceType.AssignableTo(elemType):
				// map[string][]string or map[string]interface{} - keep all values for the key
				val.SetMapIndex(key, reflect.ValueOf(v))
			default:
				// e.g. map[string]string - bind the first value only
				elem := reflect.New(elemType).Elem()
				if err := setWithProperType(elemType.Kind(), v[0], elem); err != nil {
					return err
				}
				val.SetMapIndex(key, elem)
			}
		}
		return nil
	}
```

