		t.Fatalf("gzip.NewReader: %v (body=%q)", err, rec.Body.String())
	}
	body, err := ioutil.ReadAll(gr)
	if err != nil {
		t.Fatalf("ReadAll: %v", err)
	}
	if string(body) != "" {
		t.Errorf("body = %q, want empty", string(body))
